function validTitle(t) {
  return t.length > 0 && t.length <= 80 && /^[a-zA-Z0-9 .,!?'-]+$/.test(t);
}
const titles = ['Fix my sink', '', 'Buy now!!! <script>'];
for (const t of titles) console.log(JSON.stringify(t) + ' -> ' + (validTitle(t) ? 'valid' : 'rejected'));

