function scanConfig(config) {
  const warnings = [];
  for (const [key, value] of Object.entries(config)) {
    if (/key|secret|token|password/i.test(key) && typeof value === 'string' && value.length > 0 && !value.startsWith('env:')) {
      warnings.push('WARNING: hardcoded secret in ' + key);
    }
  }
  if (warnings.length === 0) warnings.push('clean: no hardcoded secrets');
  return warnings;
}
const config = { dbPassword: 'hunter2', apiKey: 'env:STRIPE_KEY', port: 3000 };
for (const w of scanConfig(config)) console.log(w);

